      team_help: 'Invite a colleague by e-mail and choose a role: each role only sees its applications. The owner cannot be removed.',
      compliance: 'Compliance & GDPR',
      compliance_desc: 'GDPR requests, contract versions, legal exports and retention.',
      compliance_help: 'Handle each access or deletion request within 30 days, check partners signed the latest contract version and prepare DAC7 / 281.29 exports.',
      sales: 'Sales',
      sales_desc: 'Sales agents (access granted by the admin) and canvassed businesses: who prospects what, and where it stands.',
      sales_help: 'Choose here who is a sales agent: search their customer account (name or e-mail) and give access. Their "Sales" section appears in their account: they log each canvassed business, its stage, dated visits and calls, the restaurateur\'s opinion. You see everything here, per agent, and remove access whenever you want.',
