      appInstallHint_desktop: 'Tip: install the app for service. In Chrome or Edge, “Install” icon on the right of the address bar (or menu → “Install Fairide”). It then opens in its own window.',
      appSteps_android_1: 'Turn on the Bluetooth (BLE) thermal printer and enable Bluetooth on the tablet or phone.',
      appSteps_android_2: 'Tap “Connect my printer”, pick it in the list, then print a test ticket. Tick “Automatic printing” so every new order prints by itself.',
      appSteps_android_3: 'During service, keep the app open on Orders. If you close it, reconnect the printer in one click. Without a thermal printer: “Print the delivery note” sends the ticket to any Wi-Fi printer installed on the device (or through the RawBT app).',
      appSteps_ios_1: "On iPhone and iPad, the web app has no Bluetooth access (Apple limitation). Two options:",
      appSteps_ios_2: 'Open an order and tap “Print the delivery note”: Apple\'s print dialog offers any AirPrint or Wi-Fi printer on the network (Epson, Star, Brother…). Pick it once, it stays offered.',
      appSteps_ios_3: 'For a real thermal ticket printer at the counter, keep an Android tablet (even an entry-level one) connected over Bluetooth: it prints every order automatically while you manage the rest on iPhone.',
      appSteps_desktop_1: 'Turn on the Bluetooth (BLE) thermal printer and check the computer\'s Bluetooth is on (Chrome or Edge required).',
      appSteps_desktop_2: 'Click “Connect my printer”, pick it in the list, then print a test ticket. Tick “Automatic printing” so every new order prints by itself.',
      appSteps_desktop_3: 'USB or network printer (Epson, Star…) already installed on the PC: “Print the delivery note” uses it through the usual print dialog. Keep the app open on Orders during service.',
