      termsLink: 'terms and conditions',
      feesHowTitle: 'How fees are calculated',
      feesHowBody: 'For delivery, a delivery fee is added, calculated from the distance (€5 for the first kilometre, then €0.80 per started kilometre, any VAT included). It includes Fairide\'s system fee. When the available couriers ask for a higher minimum rate, this fee can be raised by €3 at most. Nothing else is added: the exact amount is shown before payment. Takeaway: no fee.',
