      vat: 'VAT',
      sellerTitle: 'Seller',
      sellerProfessional: 'professional seller.',
      sellerContract: 'The sale is concluded between you and this business; Fairide provides the platform, the payment and, where applicable, the delivery.',
      allergensTitle: 'Allergens',
      allergensAskBefore: 'the business answers your questions before you order, on',
      reportRestaurant: 'Report this business',
      rankingLink: 'How we rank businesses',
      dsaContactTitle: 'Point of contact (Digital Services Act)',
      dsaContactBody: 'Single point of contact for authorities and users (DSA, art. 11 and 12): dsa@fairide.be. Languages: French, Dutch, English. To report a product, content or a business, you can also use the "Report" link on the business page.',
      rankingPageTitle: 'How businesses are ranked · Fairide',
      rankingPageDescription: 'How Fairide orders businesses.',
      rankingTitle: 'How we rank businesses',
      ranking_orderTitle: 'The default order ("Recommended")',
      ranking_order: "When you search for a word or pick a filter, the businesses page shows a single list, with no paid position at all. Businesses in your municipality come first, then those of neighbouring municipalities, ring by ring. Your municipality is the one of your account address (its town, or failing that its postcode), otherwise the one of the address typed on the home page. Within a municipality, real businesses come before any demonstration listings, then the most recently registered business comes first. With no known municipality, or when you filter on a municipality, only this last order applies. The Search page and the map also follow this registration order, without taking your municipality into account.",
      ranking_sortsTitle: 'Filters',
      ranking_sorts: "There is no other sort for now. Filters (cuisine, municipality, searched word) remove businesses from the list: they don't reorder it.",
      ranking_rowsTitle: 'Home page rows',
      ranking_rows: "With no search or filter, the page shows rows, in this order.\n**Featured near you**: up to five businesses that have their own photo (not \"Menu only\" businesses), open ones before closed ones, then the closest to you. No position is paid here.\n**Already on Fairide**: up to eight real registered businesses whose menu is complete. The Fairide team can give some of them a rank by hand: they then come first, in the order of that rank. The others are ranked by a score: 100 points if the business is already open to customers, 30 if it has its own photo and 20 if its menu is complete; at equal score, the most recent first. No position is paid here.\n**Near you**: the 15 businesses closest to your account address, as the crow flies, across all municipalities (supermarkets excluded). If your address has no known position: your municipality, then neighbouring municipalities. If there are fewer than six, the row is completed with other businesses, in the default order.\n**Your cravings** (app only): if you picked cravings on the welcome screens (pizza, burgers…), the businesses that match them, in the same order as \"Near you\", 15 at most; these choices stay on your phone. No position is paid here.\n**Free delivery** and **Delivery from €3**: only when delivery is open and possible to you right now (address within the business's zone, a courier free). The first shows businesses that offer delivery, or offer it from an amount; the second, those whose delivery costs €3 at most.\n**Offers**: businesses running a promotion they created themselves.\n**Cuisine rows** (\"Pizza\"…), opened by Fairide: businesses of that type, main or secondary.\n**Healthy**: businesses with at least one dish they marked as such.\n**Grocery stores**: supermarkets, night shops, bakeries and butchers.\n**Discover**: up to eight businesses where you haven't ordered yet, within 10 km of your address when it has a known position.\nIn these rows (except the first four), the order is: your municipality first, then neighbouring municipalities; within a municipality, an order drawn at random for your visit. One exception: when a business has paid for a position in the row for your municipality (see below), the others keep the row's own order: most marked dishes first for Healthy; cheapest delivery first for the two delivery rows; the list order described above for the others (still random for Discover). Only \"Near you\" is completed: the other rows only show the businesses that match them.",
      ranking_notPaidTitle: 'Paid positions (“Sponsored”)',
      ranking_notPaid: "A business can pay to be placed in one of the first positions of a row on the businesses page (from 1st to 10th at most, depending on what Fairide puts on sale), for a limited period. Its card then shows the label \"Sponsored\". The limits: the position only applies in the business's own municipality, and only for customers of that municipality (that of their account or of the address typed on the home page); with no known municipality, nothing is placed this way. A position is held by one business at a time, and a business holds only one position per row. Fairide approves each request, or accepts it automatically (first come, first served) when the team has chosen that mode. There is no paid position in \"Featured near you\", \"Already on Fairide\", \"Your cravings\", the filtered list, the Search page or the map. The business must belong to the row: paying does not put a business without vegan dishes into \"Vegan\". Two clarifications: in \"Near you\", the paying business (always from your municipality) may appear even if it is not among the 15 closest; in \"Discover\", even if it was not drawn, is more than 10 km away or you have already ordered there. Apart from these labelled positions, no business pays to be placed higher: the commission (10% at most) and the subscription are the same for everyone and don't influence the display order.",
      ranking_contestTitle: 'Contesting',
      ranking_contest: 'To contest your business\'s position: contact@fairide.be. To report illegal content: the "Report" link on the business page, or dsa@fairide.be.',
      reportPageTitle: 'Report content or a business',
